function findValueOfPartition(nums) {
  // Try every way to put each element into nums1 (bit set) or nums2 (bit clear), skipping empty groups.
  const n = nums.length;
  let best = Infinity;
  for (let mask = 1; mask < 2 ** n - 1; mask++) {
    let high = -Infinity, low = Infinity;
    for (let i = 0; i < n; i++) {
      if (Math.floor(mask / 2 ** i) % 2 === 1) high = Math.max(high, nums[i]);
      else low = Math.min(low, nums[i]);
    }
    best = Math.min(best, Math.abs(high - low));
  }
  return best;
}

